// Crowe Logic living mark — the house mark, alive.
//
// This is the ONLY mark animator in the app. It used to be one of two: this
// file drove a cube in the header while a second generator inside renderer.js
// drew an unrelated radial in agent panel heads, both using the words "idle"
// and "reasoning" to mean different pictures. One shape everywhere now.
//
// Geometry comes from renderer/mark-geometry.js (generated by
// scripts/gen-mark.js), so the animated mark and the shipped icon are the same
// polygons — the app icon spins up into the running state without a cut.
//
// States:
//   rest       still
//   idle       slow rotation + breath (header, welcome hero)
//   reasoning  fast rotation, deep breath, gold arms recede and return
//   failed     motion stops, colour drains to muted
//   ping()     one-shot hexagonal ring on each tool call
//
// window.CroweMark:
//   svg()                -> SVG markup string
//   mount(el, {state})   -> { el, setState(s), ping(), rest() }
//   setState(el, state)  -> 'rest' | 'idle' | 'reasoning' | 'failed'
//   ping(el)             -> one-shot tool ring
//   start()/stop()/reseed() kept for API compatibility (no-ops: the corporate
//   palette is fixed; identity does not drift).
(function () {
  "use strict";
  const G = window.CROWE_MARK_GEOMETRY;

  function svg() {
    if (!G) return "";
    // Stagger each arm by its angle so a state change sweeps around the mark
    // instead of snapping all twelve arms at once.
    const arm = (a, kind) =>
      `<polygon class="cm-arm cm-${kind}" points="${a.pts}" style="animation-delay:${(a.deg / 360 * -1.8).toFixed(2)}s"/>`;
    return `<svg class="cl-mk" viewBox="0 0 ${G.view} ${G.view}" aria-hidden="true">`
      + `<polygon class="cm-ping" points="${G.ring}" fill="none" stroke-width="2"/>`
      + `<g class="cm-rotor"><g class="cm-breath">`
      + G.arms.blue.map((a) => arm(a, "blue")).join("")
      + G.arms.gold.map((a) => arm(a, "gold")).join("")
      + `<polygon class="cm-heart" points="${G.heart}"/>`
      + `</g></g></svg>`;
  }

  function ping(el) { if (!el) return; el.classList.remove("cl-ping-on"); void el.offsetWidth; el.classList.add("cl-ping-on"); }
  function setState(el, state) { if (el) el.dataset.state = state; }

  function mount(el, opts) {
    opts = opts || {};
    el.classList.add("cl-mark");
    el.innerHTML = svg();
    setState(el, opts.state || "rest");
    return {
      el,
      setState: (s) => setState(el, s),
      ping: () => ping(el),
      rest: () => setState(el, "rest"),
    };
  }

  const noop = () => {};
  window.CroweMark = { svg, mount, setState, ping, start: noop, stop: noop, reseed: noop };
})();
